"""MCP Server Manager for handling multiple MCP server connections."""

import json
import os
from contextlib import AsyncExitStack
from typing import List, Dict, Optional, Union
from agents.mcp import MCPServerStdio, MCPServerStdioParams, MCPServerStreamableHttp, MCPServerStreamableHttpParams
from loguru import logger

# Create a named logger for this module
logger = logger.bind(name="mcp_server_manager")

try:
    import json5
except ImportError:
    json5 = None


class MCPServerConfig:
    """Configuration for a single MCP server."""

    def __init__(self, name: str, server_type: str, **kwargs):
        self.name = name
        self.server_type = server_type

        if server_type == "stdio":
            self.command = kwargs.get("command")
            self.args = kwargs.get("args", [])
        elif server_type == "http":
            self.url = kwargs.get("url")
        else:
            raise ValueError(f"Unsupported server type: {server_type}")


class MCPServerManager:
    """Manages multiple MCP server connections."""

    def __init__(self, config_path: str = "mcp.json"):
        self.servers: Dict[str, Union[MCPServerStdio, MCPServerStreamableHttp]] = {}
        self.configs: Dict[str, MCPServerConfig] = {}
        self._initialized = False
        self._exit_stack = AsyncExitStack()
        # Load config from the same directory as this file
        if not os.path.isabs(config_path):
            config_path = os.path.join(os.path.dirname(__file__), config_path)
        self.config_path = config_path

        # Load configuration from file
        self._load_config()

    async def ensure_initialized(self):
        """Ensure servers are initialized."""
        if not self._initialized:
            await self.initialize_servers()
            self._initialized = True

    def _load_config(self):
        """Load MCP server configuration from JSON file."""
        try:
            if not os.path.exists(self.config_path):
                logger.warning(f"Config file not found: {self.config_path}")
                return

            with open(self.config_path, 'r') as f:
                if json5:
                    config_data = json5.load(f)
                else:
                    config_data = json.load(f)

            servers = config_data.get("servers", {})
            for name, server_config in servers.items():
                try:
                    config = MCPServerConfig(name=name, server_type=server_config['type'], **server_config)
                    self.add_server_config(config)
                    logger.info(f"Loaded configuration for server: {name}")
                except Exception as e:
                    logger.error(f"Failed to load config for server {name}: {e}")

        except Exception as e:
            logger.error(f"Failed to load config file {self.config_path}: {e}")

    def add_server_config(self, config: MCPServerConfig):
        """Add a server configuration."""
        self.configs[config.name] = config


    async def initialize_servers(self) -> List[Union[MCPServerStdio, MCPServerStreamableHttp]]:
        """Initialize all configured MCP servers."""
        servers = []

        for name, config in self.configs.items():
            try:
                logger.info(f"Initializing MCP server: {name}")

                if config.server_type == "stdio":
                    params = MCPServerStdioParams(
                        command=config.command,
                        args=config.args
                    )
                    server = MCPServerStdio(params, client_session_timeout_seconds=30.0)
                elif config.server_type == "http":
                    params = MCPServerStreamableHttpParams(
                        url=config.url,
                        timeout=15.0,
                        sse_read_timeout=30.0
                    )
                    server = MCPServerStreamableHttp(params, client_session_timeout_seconds=30.0)
                else:
                    logger.error(f"Unsupported server type for {name}: {config.server_type}")
                    continue

                self.servers[name] = server
                servers.append(server)

                logger.info(f"Successfully initialized MCP server: {name}")

            except Exception as e:
                logger.error(f"Failed to initialize MCP server {name}: {e}")
                raise

        return servers


    def get_servers(self) -> List[Union[MCPServerStdio, MCPServerStreamableHttp]]:
        """Get list of all initialized servers."""
        return list(self.servers.values())

    def get_server(self, name: str) -> Optional[Union[MCPServerStdio, MCPServerStreamableHttp]]:
        """Get a specific server by name.""" 
        return self.servers.get(name)

    async def __aenter__(self):
        """Async context manager entry."""
        await self.ensure_initialized()

        # Start servers using exit stack for proper cleanup
        for name, server in self.servers.items():
            logger.info(f"Starting MCP server: {name}")
            try:
                await self._exit_stack.enter_async_context(server)
            except Exception as e:
                logger.error(f"Failed to start server {name}: {e}")
                # Exit stack will clean up any servers that were started
                await self._exit_stack.aclose()
                raise
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        """Async context manager exit."""
        # This closes servers in LIFO order in the SAME task that entered them
        try:
            await self._exit_stack.aclose()
        finally:
            self.servers.clear()

from av_api.client import _make_api_request
from av_api.registry import tool


@tool
def index_data(
    symbol: str,
    interval: str,
    datatype: str = "json"
) -> dict[str, str] | str:
    """
    Returns daily, weekly, or monthly OHLC time series data for 200+ major market indices (e.g., DJI, SPX, COMP, NDX, VIX, RUT). For the full list of supported indices, use INDEX_CATALOG.

    Args:
        symbol: The index symbol (e.g., DJI for Dow Jones, SPX for S&P 500, COMP for NASDAQ Composite, NDX for NASDAQ 100, VIX for Cboe Volatility Index, RUT for Russell 2000).
        interval: Time interval between two data points. Supported values: daily, weekly, monthly.
        datatype: By default, json. Strings json and csv are accepted.

    Returns:
        OHLC time series data for the specified index.
    """
    params = {
        "symbol": symbol,
        "interval": interval,
        "datatype": datatype,
    }
    return _make_api_request("INDEX_DATA", params)


@tool
def index_catalog(
    datatype: str = "json"
) -> dict[str, str] | str:
    """
    Returns the full list of supported index symbols with their long-form names.

    Args:
        datatype: By default, json. Strings json and csv are accepted.

    Returns:
        List of supported index symbols and names.
    """
    params = {
        "datatype": datatype,
    }
    return _make_api_request("INDEX_CATALOG", params)

"""Display manager for OpenAI Agents SDK examples.

Handles formatted console output, panels, and streaming display for agent interactions.
"""

from rich.console import Console
from rich.markdown import Markdown
from rich.panel import Panel
from rich.theme import Theme
from rich.table import Table
import json


# Custom theme for event-based colors
custom_theme = Theme({
    "user": "green",
    "assistant": "cyan",
    "tool": "blue",
    "timestamp": "dim white",
})


class AgentDisplayManager:
    def __init__(self):
        self.console = Console(theme=custom_theme)

    def display_welcome(self, session_id: str):
        """Display welcome message with session info."""
        welcome_text = (
            f"Welcome to the Alpha Vantage Financial Agent! Ask questions about stocks, forex, and financial markets.\n"
            f"Session: {session_id}\n"
            f"Conversation history is automatically maintained across queries.\n"
            f"Type 'exit' or 'quit' to stop."
        )

        self.console.print(Panel(
            welcome_text,
            title="🤖 Alpha Vantage Financial Agent (with Session Memory)",
            border_style="assistant"
        ))

    def display_agent_config(self, agent_config):
        """Display agent configuration panel."""
        config_md = self._create_agent_config_md(agent_config)

        self.console.print(Panel(
            Markdown(config_md),
            title="Agent Info",
            border_style="user"
        ))

    def display_tool_execution(self, tool_name: str, arguments=None, call_id: str = None):
        """Display tool execution panel."""
        # Format arguments if provided as raw data
        if arguments is not None and not isinstance(arguments, str):
            try:
                args_text = f"```json\n{json.dumps(arguments, indent=2)}\n```"
            except:
                args_text = f"```\n{str(arguments)}\n```"
        elif isinstance(arguments, str) and not arguments.startswith('```'):
            # Handle raw JSON string arguments
            try:
                args = json.loads(arguments)
                args_text = f"```json\n{json.dumps(args, indent=2)}\n```"
            except:
                args_text = f"```\n{arguments}\n```"
        else:
            args_text = arguments or ""

        tool_md = self._create_tool_called_md(tool_name, args_text)

        title = "Tool Execution"
        if call_id:
            title = f"Tool Execution (ID: {call_id})"

        self.console.print(Panel(
            Markdown(tool_md),
            title=title,
            border_style="tool"
        ))

    def display_tool_result(self, output: str, call_id: str = None):
        """Display tool result panel."""
        # Truncate if too long
        if len(output) > 500:
            output_display = f"{output[:500]}..."
        else:
            output_display = output

        output_md = self._create_tool_output_md(output_display)

        title = "Tool Result"
        if call_id:
            title = f"Tool Result (ID: {call_id})"

        self.console.print(Panel(
            Markdown(output_md),
            title=title,
            border_style="tool"
        ))

    def display_agent_response(self, content):
        """Display agent response panel."""
        # Handle different content formats
        if isinstance(content, str):
            message_text = content
        elif isinstance(content, list):
            # Parse content array like in stream events
            for content_part in content:
                if hasattr(content_part, 'text'):
                    message_text = content_part.text
                    break
                elif isinstance(content_part, dict) and content_part.get('type') == 'output_text':
                    message_text = content_part.get('text', '')
                    break
            else:
                message_text = str(content)
        else:
            message_text = str(content)

        message_md = self._create_message_output_md(message_text)

        self.console.print(Panel(
            Markdown(message_md),
            title="Agent Response",
            border_style="assistant"
        ))

    def display_goodbye(self):
        """Display goodbye message."""
        self.console.print("Goodbye! 👋")

    def display_error(self, error: str):
        """Display error message."""
        self.console.print(f"Error: {error}")

    def display_info(self, message: str):
        """Display info message."""
        self.console.print(message)

    def display_sessions_table(self, sessions: list):
        """Display sessions in a formatted table."""
        table = Table(title="Previous Sessions")

        table.add_column("Session ID", no_wrap=True)
        table.add_column("Message Count", justify="center")
        table.add_column("First Message")
        table.add_column("Created At", no_wrap=True)
        table.add_column("Updated At", no_wrap=True)

        for session in sessions:
            table.add_row(
                session['session_id'],
                str(session['message_count']),
                session['first_message'],
                session.get('created_at', 'N/A'),
                session.get('updated_at', 'N/A')
            )

        self.console.print(table)

    def display_session_items(self, items: list):
        """Display conversation history items from a resumed session."""
        if not items:
            self.display_info("No conversation history found.")
            return

        self.console.print(Panel(
            f"Loaded {len(items)} messages from conversation history",
            title="📖 Session Resumed",
            border_style="assistant"
        ))

        # Display all conversation items using same methods as stream events
        for item in items:
            if item.get('role') == 'user':
                # Display user message
                self.console.print(Panel(
                    item.get('content', ''),
                    title="User Query",
                    border_style="user"
                ))
            elif item.get('type') == 'function_call':
                tool_name = item.get('name', 'Unknown Tool')
                arguments = item.get('arguments', '{}')
                call_id = item.get('call_id', '')
                self.display_tool_execution(tool_name, arguments, call_id)

            elif item.get('type') == 'function_call_output':
                output = item.get('output', '')
                call_id = item.get('call_id', '')
                self.display_tool_result(str(output), call_id)

            elif item.get('role') == 'assistant' and item.get('type') == 'message':
                content = item.get('content', [])
                self.display_agent_response(content)

    def _create_agent_config_md(self, agent_config) -> str:
        """Create markdown content for agent configuration."""
        return f"""**Name:** {agent_config.name}

**Model:** {agent_config.model}

**MCP Servers:** {len(agent_config.mcp_servers)} server(s)

**Instructions:** 
{agent_config.instructions}
"""

    def _create_tool_called_md(self, tool_name: str, args_text: str) -> str:
        """Create markdown content for tool execution."""
        return f"""**Tool:** {tool_name}

**Arguments:**
{args_text}
"""

    def _create_tool_output_md(self, output_display: str) -> str:
        """Create markdown content for tool output."""
        return f"""
{output_display}
"""

    def _create_message_output_md(self, message_text: str) -> str:
        """Create markdown content for final response."""
        return f"""{message_text}
"""

"""Input manager for handling user input with multi-line support."""

from typing import Tuple, List
from prompt_toolkit import prompt
from prompt_toolkit.completion import Completer, Completion
from prompt_toolkit.formatted_text import HTML
from rich.console import Console


class SlashCommandCompleter(Completer):
    """Custom completer for slash commands."""

    def __init__(self, commands: List[str]):
        self.commands = commands

    def get_completions(self, document, complete_event):
        text = document.text_before_cursor

        # Only show completions if text starts with '/'
        if text.startswith('/'):
            command_part = text[1:]  # Remove the '/'

            for command in self.commands:
                if command.startswith(command_part):
                    # Show the completion without the '/' prefix since it's already typed
                    yield Completion(
                        command[len(command_part):],
                        display=HTML(f'<b>/{command}</b>'),
                        start_position=0
                    )


class InputManager:
    def __init__(self, console: Console, slash_commands: List[str] = None):
        self.console = console
        self.eof_count = 0
        self.ctrl_c_count = 0
        self.slash_commands = slash_commands or [
            'help', 'sessions', 'clear', 'resume', 'exit', 'quit'
        ]
        self.completer = SlashCommandCompleter(self.slash_commands)

    def get_input(self) -> Tuple[str, bool, int]:
        """Get user input with support for multi-line input using EOF flags.

        Multi-line input starts with <<EOF and ends with EOF. For example:
        <<EOF
        line 1
        line 2
        EOF

        Returns:
            Tuple[str, bool, int]: A tuple containing:
                - The user input, either single line or multiple lines joined with newlines
                - A boolean indicating if the input was multi-line (True) or single-line (False)
                - The number of lines in the input

        Raises:
            EOFError: When Ctrl-D is pressed, allowing the caller to handle exit
        """
        try:
            # Get input using regular prompt with completion
            text = prompt('> ', in_thread=True, completer=self.completer)
            text = text.rstrip()

            # Reset EOF and Ctrl-C counts when user provides input
            self.eof_count = 0
            self.ctrl_c_count = 0

            # Check for multi-line input start flag
            if text == "<<EOF":
                lines = []
                while True:
                    try:
                        line = prompt('', in_thread=True, completer=self.completer)
                        if line == "EOF":
                            break
                        lines.extend(line.split("\n"))
                    except EOFError:
                        # Handle Ctrl-D during multi-line input
                        raise EOFError()
                    except KeyboardInterrupt:
                        # Handle Ctrl-C during multi-line input
                        raise KeyboardInterrupt()
                return ("\n".join(lines), True, len(lines))

            lines = text.split("\n")
            return (text, False, len(lines))
        except KeyboardInterrupt:
            self.ctrl_c_count += 1
            if self.ctrl_c_count == 1:
                self.console.print("(Press Ctrl-C again to exit)", style="dim")
                return ("", False, 0)
            else:
                # Second Ctrl-C, exit
                raise KeyboardInterrupt()
        except EOFError:
            self.eof_count += 1
            if self.eof_count == 1:
                self.console.print("(Press Ctrl-D again to exit)", style="dim")
                return ("", False, 0)
            else:
                # Second Ctrl-D, exit
                raise EOFError()

    def is_exit_command(self, text: str) -> bool:
        """Check if the input is an exit command.

        Args:
            text: The input text to check

        Returns:
            bool: True if the input is an exit command, False otherwise
        """
        return text.lower() in ['exit', 'quit', '/exit', '/quit']

